            target_value = Decimal("0.40") * self.portfolio.total_portfolio_value
            quantity = int(target_value / spy_bar.close)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            allocation = Decimal("20000")
            if self.portfolio.cash >= allocation:
                quantity = int(allocation / aapl_bar.close)
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

    def _spy_crosses_above_sma(self):
        return (
            len(self.spy_closes) == 2
            and len(self.spy_smas) == 2
            and self.spy_closes[0] <= self.spy_smas[0]
            and self.spy_closes[1] > self.spy_smas[1]
        )

    def _spy_crosses_below_sma(self):
        return (
            len(self.spy_closes) == 2
            and len(self.spy_smas) == 2
            and self.spy_closes[0] >= self.spy_smas[0]
            and self.spy_closes[1] < self.spy_smas[1]
        )

