            return

        self._evaluate_spy(data.bars[spy])
        self._evaluate_aapl(data.bars[aapl])

    def _evaluate_spy(self, bar: TradeBar):
        if not self.spy_closes.is_ready or self.spy_order_id is not None:
            return

        today_close = float(self.spy_closes[0])
        yesterday_close = float(self.spy_closes[1])
        today_sma = sum(float(self.spy_closes[i]) for i in range(100)) / 100
        yesterday_sma = sum(float(self.spy_closes[i]) for i in range(1, 101)) / 100

        crossed_below = yesterday_close >= yesterday_sma and today_close < today_sma
        crossed_above = yesterday_close <= yesterday_sma and today_close > today_sma

        if self.spy_lot > 0:
            if crossed_below:
                ticket = self.market_order(self.symbols["SPY"], -self.spy_lot)
                self.spy_order_id = ticket.order_id
        elif crossed_above:
            quantity = self.calculate_order_quantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                ticket = self.market_order(self.symbols["SPY"], quantity)
                self.spy_order_id = ticket.order_id

    def _evaluate_aapl(self, bar: TradeBar):
        if not self.aapl_rsi.is_ready or self.aapl_order_id is not None:
            return

        if self.aapl_lot > 0:
            if self.aapl_rsi.current.value > self.aapl_rsi_threshold:
                ticket = self.market_order(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_order_id = ticket.order_id
        elif self.aapl_red_streak >= 3 and self.portfolio.cash >= 20_000:
            quantity = int(20_000 // float(bar.close))
            if quantity > 0:
                ticket = self.market_order(self.symbols["AAPL"], quantity)
                self.aapl_order_id = ticket.order_id

    def on_order_event(self, order_event: OrderEvent):
        if order_event.status not in [OrderStatus.PARTIALLY_FILLED, OrderStatus.FILLED]:
            return

        if order_event.symbol == self.symbols["SPY"]:
            self.spy_lot += int(order_event.fill_quantity)
            if order_event.status == OrderStatus.FILLED:
                self.spy_order_id = None
        elif order_event.symbol == self.symbols["AAPL"]:
            self.aapl_lot += int(order_event.fill_quantity)
            if order_event.status == OrderStatus.FILLED:
                self.aapl_order_id = None

